<a href="<?= e(url('admin/orders')) ?>" class="small">&larr; All orders</a>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 my-2"><h1 class="h4 fw-bold mb-0">Order <?= e($o['order_no']) ?></h1><div><?= status_badge($o['order_status']) ?> <?= status_badge($o['payment_status']) ?></div></div>
<div class="row g-3"><div class="col-lg-8">
<div class="bg-white rounded-3 shadow-sm p-3 mb-3"><h2 class="h6">Items</h2><table class="table table-sm mb-0"><tbody><?php foreach ($items as $it): ?><tr><td><?= e($it['name']) ?><div class="small text-muted"><?= e($it['sku']) ?></div></td><td>×<?= (int)$it['qty'] ?></td><td class="text-end"><?= e(inr($it['unit_price'] * $it['qty'])) ?></td></tr><?php endforeach; ?>
<tr><td colspan="2" class="text-end">Shipping + fees</td><td class="text-end"><?= e(inr($o['shipping_fee'] + $o['cod_fee'])) ?></td></tr><?php if ($o['coupon_discount'] > 0): ?><tr><td colspan="2" class="text-end">Coupon <?= e($o['coupon_code']) ?></td><td class="text-end">− <?= e(inr($o['coupon_discount'])) ?></td></tr><?php endif; ?>
<tr class="fw-bold"><td colspan="2" class="text-end">Total</td><td class="text-end"><?= e(inr($o['total'])) ?></td></tr></tbody></table></div>
<div class="bg-white rounded-3 shadow-sm p-3 mb-3"><h2 class="h6">History</h2><?php foreach ($events as $e): ?><div class="small border-bottom py-1"><strong><?= e(status_label($e['status'])) ?></strong> — <?= e($e['note']) ?> <span class="text-muted">(<?= e(date('j M, g:i A', strtotime($e['created_at']))) ?><?= $e['simulated'] ? ', simulated tracking' : '' ?>)</span></div><?php endforeach; ?></div>
<?php if ($returns): ?><div class="bg-white rounded-3 shadow-sm p-3 mb-3"><h2 class="h6">Returns</h2><?php foreach ($returns as $r): ?><div class="small py-1"><?= e(ucfirst($r['type'])) ?>: <?= e($r['item_name']) ?> — <?= e($r['reason']) ?> <?= status_badge($r['status']) ?></div><?php endforeach; ?><a href="<?= e(url('admin/returns')) ?>" class="small">Manage returns</a></div><?php endif; ?>
<?php if ($refunds): ?><div class="bg-white rounded-3 shadow-sm p-3"><h2 class="h6">Refunds</h2><?php foreach ($refunds as $r): ?><div class="d-flex justify-content-between align-items-center small py-1"><span><?= e(inr($r['amount'])) ?> via <?= e($r['method']) ?> — <?= e($r['note']) ?> <?= status_badge($r['status']) ?></span>
<?php if ($r['status'] !== 'processed'): ?><form method="post" action="<?= e(url('admin/refunds/' . $r['id'] . '/process')) ?>" data-confirm="Process this refund of <?= e(inr($r['amount'])) ?>?"><?= csrf_field() ?><input type="hidden" name="back_order" value="<?= e($o['order_no']) ?>"><button class="btn btn-sm btn-dark">Process</button></form><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?>
</div><div class="col-lg-4">
<div class="bg-white rounded-3 shadow-sm p-3 mb-3"><h2 class="h6">Customer</h2><div class="small"><?= e($o['customer_name']) ?><br><?= e($o['customer_email']) ?><br><?= e($o['customer_phone']) ?><hr class="my-2"><?= e($o['ship_name']) ?><br><?= e($o['ship_line1']) ?><?= $o['ship_line2'] ? ', ' . e($o['ship_line2']) : '' ?><br><?= e($o['ship_city']) ?>, <?= e($o['ship_state']) ?> - <?= e($o['ship_pincode']) ?></div></div>
<?php if (!in_array($o['order_status'], ['cancelled', 'pending_payment', 'delivered'], true)): ?>
<div class="bg-white rounded-3 shadow-sm p-3 mb-3"><h2 class="h6">Update tracking <small class="text-muted">(simulated)</small></h2><form method="post" action="<?= e(url('admin/orders/' . $o['order_no'] . '/status')) ?>"><?= csrf_field() ?>
<select class="form-select form-select-sm mb-2" name="status" aria-label="New status"><?php $cur = array_search($o['order_status'], \App\Services\OrderService::FLOW, true); foreach (\App\Services\OrderService::FLOW as $i => $s): if ($i <= $cur) continue; ?><option value="<?= $s ?>"><?= e(status_label($s)) ?></option><?php endforeach; ?></select>
<input class="form-control form-control-sm mb-2" name="note" maxlength="250" placeholder="Note (optional)" aria-label="Note"><button class="btn btn-warning btn-sm w-100">Update</button></form></div><?php endif; ?>
<?php if ($o['order_status'] !== 'cancelled' && $o['order_status'] !== 'delivered'): ?><form method="post" action="<?= e(url('admin/orders/' . $o['order_no'] . '/cancel')) ?>" data-confirm="Cancel this order and restore stock?"><?= csrf_field() ?><input class="form-control form-control-sm mb-2" name="reason" placeholder="Reason" maxlength="200"><button class="btn btn-outline-danger btn-sm w-100">Cancel order</button></form><?php endif; ?>
</div></div>
